def transform(grid):
    h, w = len(grid), len(grid[0])
    from collections import deque

    # The colored seed defines a stencil. Repeat its shape at every
    # matching placement, changing only background cells to the seed color.
    colors = {v for row in grid for v in row if v not in (0, 1, 4, 5, 6)}
    color = next(iter(colors))
    cells = [(r, c) for r in range(h) for c in range(w) if grid[r][c] == color]
    r0 = min(r for r, c in cells)
    c0 = min(c for r, c in cells)
    shape = {(r-r0, c-c0) for r, c in cells}
    sh = max(r for r, c in shape) + 1
    sw = max(c for r, c in shape) + 1
    out = [row[:] for row in grid]

    # Copy the seed stencil to placements whose non-background cells agree
    # with the original stencil; the seed itself is also retained.
    for r in range(h-sh+1):
        for c in range(w-sw+1):
            if all(grid[r+dr][c+dc] in (0, color) for dr, dc in shape):
                for dr, dc in shape:
                    if grid[r+dr][c+dc] == 0:
                        out[r+dr][c+dc] = color
    return out
